```java
import java.io.*;
import java.util.ArrayList;
import java.util.List;

public class CommandHandler {
    // This method is secure because it uses a ProcessBuilder with a 
    // parameterized list of arguments, preventing shell metacharacters 
    // from being interpreted as new commands.
    public void pingHost(String host) {
        try {
            // By passing the command and arguments as separate elements in a list,
            // the OS treats the entire 'host' string as a single argument 
            // rather than a part of a shell command string.
            List<String> command = new ArrayList<>();
            command.add("ping");
            command.add("-c");
            command.add("4");
            command.add(host); // Even if this contains ";", it's treated as a literal filename/IP

            ProcessBuilder pb = new ProcessBuilder(command);
            Process process = pb.start();

            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
